#!/usr/bin/env bash
# The exact container launch used for the benchmark (generated by B70 Control from b70-control-recipe.json).
# Build the image first:  docker build --network host -t b70-inkling-vllm:2026-11-23 .   (in this folder)
# Model: thinkingmachines/Inkling-2-Mini at revision ed40e7da625f594fc9c4990f5f66be24873c22d7
#   (model-00001-of-00001.safetensors sha256 65e60f51aa1284d4fb022584908c315270334d991828bb774af60584523539d1).
# The concurrency tests ran the same command with --max-num-seqs 8; everything else used 1.
set -euo pipefail
MODEL_DIR="${MODEL_DIR:-$HOME/models/Inkling-2-Mini}"
MAX_SEQS="${MAX_SEQS:-1}"

docker run -d --name b70-inkling2-vllm --restart unless-stopped --ipc host -p 8000:8000 \
  --device /dev/dri --group-add "$(getent group render | cut -d: -f3)" -v /dev/dri:/dev/dri:ro \
  -v "$MODEL_DIR":/model:ro \
  -e VLLM_TARGET_DEVICE=xpu -e ZE_FLAT_DEVICE_HIERARCHY=COMPOSITE -e ZE_AFFINITY_MASK=0 -e VLLM_XPU_ENABLE_XPU_GRAPH=1 \
  -e PYTORCH_ALLOC_CONF=expandable_segments:True \
  -e INK2_CUTLASS_MOE=1 -e INK2_SYCL_DECODE_ATTN=1 -e ZE_ENABLE_PCI_ID_DEVICE_ORDER=1 \
  -e VLLM_WORKER_MULTIPROC_METHOD=spawn -e VLLM_RPC_BASE_PATH=/tmp/ink2-ipc \
  --entrypoint bash b70-inkling-vllm:2026-11-23 -lc "set -e; exec vllm serve /model \
    --served-model-name inkling-2-mini --dtype bfloat16 --max-model-len 131072 --gpu-memory-utilization 0.92 \
    --kv-cache-dtype fp8 --port 8000 --host 0.0.0.0 --max-num-seqs $MAX_SEQS --max-num-batched-tokens 2048 \
    --enable-prefix-caching --speculative-config '{\"method\":\"dspark\",\"num_speculative_tokens\":7}' \
    --enable-auto-tool-choice --tool-call-parser inkling --reasoning-parser inkling --block-size 64 \
    -cc.mode=none -cc.cudagraph_mode=FULL_DECODE_ONLY --limit-mm-per-prompt '{\"image\":4}' --enable-prompt-tokens-details"
